import{j as e}from"./motion-BhhR4jgw.js";import{u as h,r as c,n as m}from"./index-D1EikCdH.js";import{u as p,r as u,L as l}from"./react-Bu9c7T3F.js";const w=[["methods","How the water is read"],["grade","The lake grade"],["validation","Water memory, tested"],["our-read","Our read for renters and buyers"],["this-week","What to do this week"],["rain","Rain heads-up"],["heat","Summer heat"],["standing-water","Standing water from people"],["lake-causes","Why a lake is like this"],["evidence","Evidence and dossiers"],["rules","Access rules"],["privacy","Privacy"],["limits","Limits"],["data","Data and credits"],["open-source","Open source and AWS"],["credit","Who made it"]],f=[{tier:"Little water memory",flooded:6,random:102},{tier:"Some water memory",flooded:23,random:99},{tier:"Strong water memory",flooded:10,random:39}],g=[["Bengaluru",.852],["Delhi",.779],["Hyderabad",.571],["Chennai",.548]];function t({id:r,children:n}){return e.jsx("h2",{id:r,className:"scroll-mt-24 pt-16 text-[clamp(1.8rem,3.4vw,2.4rem)] first:pt-0",children:n})}function a({children:r}){return e.jsx("p",{className:"mt-4 text-[16.5px] leading-[1.65]",children:r})}function b(){return e.jsxs("figure",{className:"mt-6",children:[e.jsx("div",{className:"space-y-4",children:f.map(r=>{const n=100*r.flooded/39,o=100*r.random/240;return e.jsxs("div",{children:[e.jsx("div",{className:"text-[15px] font-semibold",children:r.tier}),e.jsxs("div",{className:"mt-1.5 grid grid-cols-[8.5rem_minmax(0,1fr)_3rem] items-center gap-x-3 gap-y-1 text-[13.5px]",children:[e.jsx("span",{className:"text-ink-2",children:"Flooded localities"}),e.jsx("span",{className:"h-3 rounded-sm bg-paper-3",children:e.jsx("span",{className:"block h-full rounded-sm bg-built",style:{width:`${n}%`}})}),e.jsxs("span",{className:"num text-right text-[14px]",children:[Math.round(n),"%"]}),e.jsx("span",{className:"text-ink-2",children:"Random built-up"}),e.jsx("span",{className:"h-3 rounded-sm bg-paper-3",children:e.jsx("span",{className:"block h-full rounded-sm bg-memory",style:{width:`${o}%`}})}),e.jsxs("span",{className:"num text-right text-[14px]",children:[Math.round(o),"%"]})]})]},r.tier)})}),e.jsx("figcaption",{className:"muted mt-3 text-[13.5px]",children:"Share of each group in each tier: 39 localities reported flooded against 240 random built-up places in the same four cities."})]})}function k(){const{lang:r,t:n}=h(),{hash:o}=p(),{data:d}=c({queryKey:["policies"],queryFn:()=>m.get("/v1/policies"),staleTime:1/0});return u.useEffect(()=>{if(!o)return;const s=document.getElementById(o.slice(1));s&&window.setTimeout(()=>s.scrollIntoView({block:"start"}),50)},[o]),e.jsxs("div",{lang:"en",className:"mx-auto max-w-[1400px] px-4 py-8 sm:px-6",children:[r!=="en"&&e.jsx("p",{className:"mb-6 rounded-md bg-paper-2 px-3 py-2 text-[15px]",children:n("common.englishOnly")}),e.jsx("h1",{className:"max-w-[16ch]",children:"How JalSmriti works"}),e.jsx("p",{className:"mt-5 max-w-[60ch] text-[1.15rem] leading-relaxed text-ink-2",children:"JalSmriti reads the public satellite record of India and Nepal to answer two questions in plain words: what does this place remember about water, and what is happening to this lake. Everything below is how those answers are made, how well they hold up, and where they stop."}),e.jsxs("div",{className:"mt-12 grid gap-12 lg:grid-cols-[15rem_minmax(0,1fr)] [&>*]:min-w-0",children:[e.jsx("nav",{"aria-label":"On this page",className:"hidden lg:block",children:e.jsx("ul",{className:"sticky top-24 space-y-2 border-l-2 border-line pl-4 text-[15px]",children:w.map(([s,i])=>e.jsx("li",{children:e.jsx("a",{href:`#${s}`,className:"text-ink-2 hover:text-ink",children:i})},s))})}),e.jsxs("div",{className:"min-w-0 max-w-[70ch]",children:[e.jsx(t,{id:"methods",children:"How the water is read"}),e.jsxs(a,{children:[e.jsx("b",{children:"Where water used to be."})," The JRC Global Surface Water record classifies every 30 m Landsat pixel from 1984 to 2020. A pixel that held water in at least 5% of clear observations counts as historic water. Its transition class says whether that water is still there, became seasonal, or was lost. Water bodies are the connected patches of historic water larger than 2 ha (0.5 to 1 ha in the hill and delta areas), split into lakes and river stretches by shape. Sea water is removed using elevation."]}),e.jsxs(a,{children:[e.jsx("b",{children:"How full each lake got, every year."})," For each monsoon season since 1987 JalSmriti picks the clearest post-monsoon scenes: Landsat 4 to 9 until 2015, Sentinel-2 from 2016. A pixel is water when the modified normalised difference water index (MNDWI) is above 0 and short-wave infrared reflectance is below 0.10, or when the Sentinel-2 scene classifier calls it water. A look counts for a lake only if at least 90% of the lake is clear, with no cloud or shadow within 150 m. That gives a water spread for every season: the bars on each lake page."]}),e.jsxs(a,{children:[e.jsx("b",{children:"What replaced the lost water."})," Impact Observatory's 10 m annual land cover (2017 to 2023) says what the lost water became: built-up, bare ground, crops or vegetation. An old lake bed counts as built over only where it is built-up in the latest years. ESA WorldCover 2021 is kept as a second opinion."]}),e.jsxs(a,{children:[e.jsx("b",{children:"How the ground drains."})," From the 30 m Copernicus elevation model, JalSmriti fills depressions (priority flood) to find bowls where rain ponds, traces D8 drainage lines, and measures each pixel's height above the nearest drainage line (HAND)."]}),e.jsxs(a,{children:[e.jsx("b",{children:"Floods seen by radar."})," Sentinel-1 radar sees through monsoon cloud. Since 2017, each pass over a place is compared with the same orbit in other years within 20 days of the same date. Water that is dark (below −18 dB, VV) and at least 3 dB darker than usual for that time of year is unusual standing water. Comparing with the same season is what keeps flooded paddy fields from looking like floods. At least 0.24 ha within 300 m counts as a sighting."]}),e.jsxs(a,{children:[e.jsx("b",{children:"Rain."})," NASA POWER's corrected monthly precipitation gives each lake its monsoon total for every season. Only complete seasons are used."]}),e.jsxs(a,{children:[e.jsx("b",{children:"The latest look."})," The newest Sentinel-2 scene of the last 120 days that sees the lake clearly gives the current open water, the share choked by floating weeds (vegetation with NDVI above 0.35 inside the usual water spread) and a colour index that can point to algal blooms."]}),e.jsx(t,{id:"grade",children:"The lake grade"}),e.jsx(a,{children:"The grade is four parts of 25 points each, added up and banded: A from 80, B from 65, C from 50, D from 35, E below. A part with no data is left out and the others are rescaled."}),e.jsxs("ul",{className:"mt-4 list-disc space-y-2 pl-6 text-[16.5px] leading-[1.6]",children:[e.jsxs("li",{children:[e.jsx("b",{children:"Water held now."})," The median water spread of the four most recent seasons, against the median of seasons before 2011 that had monsoon rain within 25% of the same total. Holding as much as then earns all 25 points."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Old lake bed still open."})," Full points with nothing built on the historic spread, none once 30% is built over."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Open water surface."})," Full points with no floating weeds, none at 60% weed cover."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Water spread kept since 1984."})," Full points with no water lost, none once half of it is gone."]})]}),e.jsx(a,{children:"Storage lost is the lost spread times an assumed depth of 1 to 2 m. It is a range on purpose: depths are not measured."}),e.jsx(t,{id:"validation",children:"Water memory, tested"}),e.jsx(a,{children:"A place check compares five signals with 240 random built-up places in Bengaluru, Chennai, Hyderabad and Delhi: the deepest hollow within 300 m, old water beds built over within 2 km, water lost within 1 km, water ever seen within 1 km, and the lowest height above a drainage line within 300 m. The water memory index is the average of the five percentile ranks, with equal weights that were never fitted to the test. Strong is 70 or more, some is 45 to 70, little is below 45. A radar sighting lifts a place by one tier."}),e.jsx(a,{children:"To test it, we collected 39 localities reported flooded in widely covered events: Bengaluru in 2022, Chennai in 2015 and 2023, Hyderabad in 2020, and Delhi and Gurugram in 2023. Each point is a locality centre, not the exact flooded street. Pick one flooded locality and one random built-up place: the flooded one has the higher index 68.5% of the time (AUC 0.685, where 0.5 would be chance)."}),e.jsx(b,{}),e.jsx("div",{className:"mt-8 grid grid-cols-2 gap-4 sm:grid-cols-4",children:g.map(([s,i])=>e.jsxs("div",{children:[e.jsx("div",{className:"muted text-[14px]",children:s}),e.jsx("div",{className:"num text-[1.9rem] leading-none",children:i.toFixed(2)})]},s))}),e.jsx("p",{className:"muted mt-2 text-[13.5px]",children:"AUC by city."}),e.jsx(a,{children:"It works best in Bengaluru, a city built over its tanks, and on Delhi's Yamuna floodplain. It is weak in Chennai and Hyderabad, where the worst floods came from extreme rain and breached lakes, and spread far beyond any old water bed. So read the index as history and terrain: a place with strong water memory deserves questions before you buy or build, and a place with little memory can still flood. The test data and script are in the repository (docs/validation-data)."}),e.jsx(t,{id:"our-read",children:"Our read for renters and buyers"}),e.jsx(a,{children:"Someone about to rent or buy a home answers four quick questions on the place page: renting or buying, which floor, a car in basement parking, and elderly people or small children at home. JalSmriti then gives a clear verdict: look elsewhere, think twice, fine with checks, or good to go. With it come why, what is in the place's favour, what is against it, and what to do if you still like it. The answers stay on your device; if you download the signed report, they go into it and the signature covers the verdict too."}),e.jsxs(a,{children:[e.jsx("b",{children:"How it is decided."})," By fixed points, not by an AI. The place's water memory gives 4 points for strong, 3 for some and 0 for little. The spot having been water in at least 5% of satellite looks from 1984 to 2020 adds 3 (4 from 20%). Low ground or a hollow adds 1, both together add 2, and a hollow 3 m deep adds one more. Old lakes built over within 2 km (5 ha or more) add 1. Radar sightings add 2 (3 from three sightings), and standing water reported by people within 1 km in the last year adds 1 (2 from three reports). Then the family: a first or second floor takes away 2, a third floor or above 3, an independent house adds 1. Basement parking adds 2 and elderly people or small children add 1 once the place itself scores 3 or more. Buying adds 1 where there is an old lake bed at or near the spot, for the legal risk. From 8 points the verdict is look elsewhere, 5 to 7 think twice, 2 to 4 fine with checks, and 1 or less good to go. A place that scores 3 or more on its own is never good to go, whatever the floor, because the street, the basement and the power still go under. A flat on the third floor or above is never look elsewhere: the family can be stranded there, but not flooded."]}),e.jsxs(a,{children:[e.jsx("b",{children:"Tested."}),' For a family renting a ground-floor flat, the verdict says think twice or look elsewhere at 82% of the 39 localities reported flooded, against 52% of the 240 random built-up places (radar left out). Look elsewhere is three times as common at the flooded ones: 15% against 5%. So a warning means "check before you sign", not "never live here". The Past floods page runs the same verdict on 16 places that flooded between 2020 and 2026.']}),e.jsxs(a,{children:[e.jsx("b",{children:"Not advice."})," It is a reading of open satellite records and your answers, not a survey, a legal opinion or financial advice. Visit after heavy rain, ask neighbours and check the records before you sign."]}),e.jsx(t,{id:"this-week",children:"What to do this week"}),e.jsx(a,{children:'A place check ends with steps for this week, in two lists: one for someone about to rent or buy, one for someone who already lives there. The home page asks "What brings you here?" and opens the matching list; the place page switches between them.'}),e.jsxs(a,{children:[e.jsx("b",{children:"Where the steps come from."})," Each step follows from the place's own record by a fixed rule, not from an AI. Dates when monsoon radar saw standing water become questions to ask about those days. Strong water memory, ground less than 1 m above a drainage line or a hollow 1 m deep or more add advice about floors, basements and plinths. Old lake beds built over nearby (1 ha or more within 2 km) add a check of the land's survey number against the village map and the lake's full tank level. Ground that reaches 42 °C on summer mornings adds advice about shade and roofs. A list has at most seven steps, and your ticks stay on your device."]}),e.jsxs(a,{children:[e.jsx("b",{children:"The same steps everywhere."})," The place page, the signed report and the narration take the steps from the same rules and say them in the same words, in your language."]}),e.jsxs(a,{children:[e.jsx("b",{children:"The signed report."})," The place report is a PDF of one or two pages for the reader you chose: what the place remembers, the time-lapse, radar, summer heat, standing water people reported nearby, this week's steps and, for someone renting or buying, four questions for the owner or seller. It is signed with the same AWS KMS key as the dossiers, and its verify page checks it in your browser: change one byte of the PDF and the check fails."]}),e.jsxs(a,{children:[e.jsx("b",{children:"Listening."})," Place and lake reports can be read aloud in Hindi or English by Amazon Polly, with the neural voice Kajal. Each text becomes audio once and is kept, so playing it again costs nothing."]}),e.jsx(t,{id:"rain",children:"Rain heads-up"}),e.jsx(a,{children:"Follow a place and JalSmriti emails you when heavy rain is forecast there for today or tomorrow. Every morning at 06:15 India time, a scheduled job reads the forecast for every followed place from Open-Meteo, which blends national and global weather models at about 10 to 25 km."}),e.jsxs(a,{children:[e.jsx("b",{children:"When you get an email."})," Rain is graded with the India Meteorological Department's categories for a day: light from 2.5 mm, moderate from 15.6 mm, heavy from 64.5 mm, very heavy from 115.6 mm and extremely heavy from 204.5 mm. Every followed place gets a heads-up for heavy rain. Places with a water memory flood with less, so they get one earlier: strong water memory from 35 mm in a day or 15 mm in one hour, some water memory from 50 mm in a day or 20 mm in one hour. These are working thresholds, not fitted to flood records."]}),e.jsxs(a,{children:[e.jsx("b",{children:"The email."})," It says how much rain is expected, how heavy the worst hour may be, the chance of rain, why this place floods and four things to do before the rain, in the language you chose. A rainy day is announced once, and a place gets at most one email a day. Each person has their own Amazon SNS topic, so you confirm your address once however many places you follow (up to ten). You can send yourself a test email from My activity."]}),e.jsxs(a,{children:[e.jsx("b",{children:"Not an official warning."})," Forecasts can be wrong, and rain in your street can be heavier or lighter. Warnings from IMD and the National Disaster Management Authority (in Nepal, DHM and NDRRMA) come first. The place page also shows the next three days."]}),e.jsx(t,{id:"heat",children:"Summer heat"}),e.jsx(a,{children:"Lost lakes make streets hotter as well as wetter. A place check measures how hot the ground gets on summer mornings before the monsoon, and compares it with built-up ground, lake water and trees nearby."}),e.jsxs(a,{children:[e.jsx("b",{children:"How it is measured."}),' Landsat 8 and 9 carry a thermal sensor that measures the temperature of the surface itself: roofs, roads, soil, tree canopy and water. JalSmriti looks at the passes between 15 March and 31 May of the last three summers with less than 30% cloud, keeps up to 8 of the clearest, spread over the three summers, leaves out cloudy pixels and anything outside 5 to 75 °C, and takes the median of each pixel. "Here" is the median within 300 m of the place. It is compared with the medians over built-up ground and trees (Impact Observatory land cover, 2023) and over water that was there in at least half of all observations from 1984 to 2020, in a window 6 km across.']}),e.jsxs(a,{children:[e.jsx("b",{children:"Reading it."})," Landsat passes at about 10:30 to 11:00 in the morning, so afternoons are hotter still, and this is the ground, not the air. The thermal pixels are 100 m across, so a pond smaller than that reads warm, mixed with the ground around it. At least two clear passes are needed; in cloudy places there may not be enough."]}),e.jsx(t,{id:"standing-water",children:"Standing water from people"}),e.jsx(a,{children:"Satellites miss water that drains in hours; people standing in it do not. Anyone signed in can report standing water with a photo, the location and how deep it is: ankle, knee, waist or above car wheels. Reports appear on a live map of the last 48 hours or 7 days, and a place page counts the reports within 1 km in the last year."}),e.jsxs(a,{children:[e.jsx("b",{children:"Checks."})," A report goes through the same privacy steps as lake photos: the original is fingerprinted and kept private, Amazon Rekognition holds back unsafe photos and finds faces, which are blurred, and the public copy carries no phone metadata. The photo's own location is used when it has one, otherwise the phone's; if the two are more than 2 km apart the photo wins and the report is flagged. A photo taken more than 48 hours before it was sent is marked as old."]}),e.jsxs(a,{children:[e.jsx("b",{children:"AI and people."})," Amazon Nova looks at the photo and says whether standing water is visible and how deep, in one plain sentence. That is a hint, never a verdict: a report goes on the map at once unless Nova is at least 60% sure there is no water, and then it waits for a verifier. NGO verifiers in the area confirm or reject reports with a note, under the access rules below, and nobody can review their own report."]}),e.jsx(t,{id:"lake-causes",children:"Why a lake is like this"}),e.jsxs(a,{children:["Each lake page reads the likely causes of its state from its own record, most serious first, and says what each one rests on. ",e.jsx("b",{children:"Built on its bed"}),": buildings and roads on the old lake bed, from Sentinel-2 land cover over the 1984 to 2020 water history. ",e.jsx("b",{children:"Filled in or drying out"}),": lost water spread that is now bare ground. ",e.jsx("b",{children:"Covered by plants"}),": lost water spread that now shows as plants from space. That can be scrub, fields or a thick mat of water hyacinth, which land-cover maps often call crops, so when the open water is choked with weeds too the page says that is the likely reading. ",e.jsx("b",{children:"Less water reaches it"}),": in recent monsoons it held under 80% of what it held in past years of similar rain. ",e.jsx("b",{children:"Choked by weeds and algae"}),": 20% or more of the water under floating weeds, or an algal colour, on the latest clear Sentinel-2 image; both feed on nutrients, usually untreated sewage. ",e.jsx("b",{children:"Holding up"}),": none of these."]}),e.jsxs(a,{children:[e.jsx("b",{children:"What would help."})," Each cause brings actions for residents (photographs with location on, the RTI request, watching the lake, a signed dossier, checking a home before renting nearby, walking the inflow channels after rain, reporting sewage) and asks for the authorities (survey and mark the boundary and buffer, remove buildings on the bed, reconnect the inflow channels and desilt, stop debris dumping, stop sewage and run the treatment plants, remove weeds regularly). The page also says how much monsoon water the lost spread would hold again if restored, 1 to 2 m deep."]}),e.jsxs(a,{children:[e.jsx("b",{children:"In the news."})," Recent headlines naming the lake come from Google News search, over the past year, and from the GDELT Project's open index of world news when Google News does not answer (GDELT covers the last three months and is asked at most once every five seconds across the whole site). Simple keywords tag each headline as flooding, encroachment, pollution or restoration, and only tagged headlines are shown, so a crime story that happens to name the lake is left out. Each answer is kept for 12 hours, and each article stays on its publisher's site. A water body without a name of its own has no news to search for."]}),e.jsxs(a,{children:[e.jsx("b",{children:"Names."}),` A water body that no map names (OpenStreetMap through Photon, then GeoNames) is named after what is near it: the nearest named lake within 2 km ("Water body near Bellandur Lake" within 1 km, "Water body 1.9 km south of Agara Lake" beyond), else its locality, else the nearest named lake within 6 km, else a neighbour's locality, else the area. Where two get the same name, the side of the lake tells them apart. The lake page says where each name came from.`]}),e.jsx(t,{id:"evidence",children:"Evidence and dossiers"}),e.jsxs(a,{children:[e.jsx("b",{children:"Photos."}),' A photo goes straight from the phone to a private Amazon S3 bucket. A queue then hands it to a function that fingerprints the original (SHA-256), reads its time and GPS and checks the GPS against the lake outline: within 30 m is "at the lake", within 400 m is "near". Amazon Rekognition screens it for unsafe content and finds faces, which are blurred in the public copy. The public copy carries no phone metadata. ',e.jsx("b",{children:"Is it the lake at all?"})," Three independent checks keep out screenshots, documents, posters, drawings and photos of something else: Rekognition counts the printed words it can read (25 or more with no outdoor scene means a screenshot or document), Rekognition's labels (a poster, a document, a drawing, and no outdoor scene), and Amazon Nova, asked whether this is a real photograph taken at a lake, its banks or the land around it. Such an upload is kept private with the reason, never reaches the public page, the verifiers or the ledger, and the uploader is told why. When Nova says no but Rekognition sees water, a verifier decides. Amazon Nova also describes what the photo shows in fixed categories (dumping, sewage, construction and so on); that description is a hint for the verifier, never a verdict."]}),e.jsxs(a,{children:[e.jsx("b",{children:"Review."})," An NGO verifier for the area confirms or rejects each photo with a note. The rules below decide who may do that, and every decision goes into the lake's ledger."]}),e.jsxs(a,{children:[e.jsx("b",{children:"The dossier."})," The code computes the facts first. An agent built with Strands Agents on Amazon Bedrock (Amazon Nova) then drafts a formal letter, reading those facts through three tools. Every number in its draft must appear in the facts; if one does not, the draft is redone, and after repeated failures a fixed template is used instead. Amazon Translate makes the second language (Nepali, Assamese and Odia go through Amazon Nova), and the numbers are checked again after translation. The PDF carries the facts, the time-lapse, the photos and both letters."]}),e.jsxs(a,{children:[e.jsx("b",{children:"Signature and ledger."})," JalSmriti writes a short statement with the dossier's content fingerprint, the PDF fingerprint and the time, and signs it with an ECDSA P-256 key held in AWS KMS: the private key cannot be exported, even by the operator. Anyone can check the signature in the browser on the dossier's verify page. Each lake also has an append-only hash chain of photos, reviews, dossiers, submissions and responses; changing an old entry breaks every hash after it."]}),e.jsxs(a,{children:[e.jsx("b",{children:"Right to Information."})," A lake page drafts a request for the lake's official records under India's Right to Information Act 2005 or Nepal's Right to Information Act 2007: survey numbers and the full tank level boundary, encroachments and the action taken, building permissions, works and complaints. You can copy, download or print it. If you record that you filed it, the lake's ledger shows the filing and the date a reply is due: 30 days in India, 15 in Nepal."]}),e.jsx(t,{id:"rules",children:"Access rules"}),e.jsx(a,{children:"Reading is open to everyone. Every write, and every look at a review queue or audit log, is decided by Cedar, the open-source policy language from AWS. The decision and the rule that made it are written to the area's audit log, denials included."}),d&&e.jsxs(e.Fragment,{children:[e.jsx("ul",{className:"mt-4 space-y-2 text-[16px]",children:Object.entries(d.rules).map(([s,i])=>e.jsxs("li",{className:"grid gap-x-4 sm:grid-cols-[17rem_minmax(0,1fr)]",children:[e.jsx("code",{className:"text-[13.5px] text-memory",children:s}),e.jsx("span",{children:i})]},s))}),e.jsxs("details",{className:"mt-5",children:[e.jsx("summary",{className:"cursor-pointer text-[15px] font-semibold",children:"The policies as written"}),e.jsx("pre",{className:"mt-3 max-h-[28rem] overflow-auto rounded-lg bg-paper-2 p-4 font-mono text-[12.5px] leading-relaxed",children:d.cedar})]})]}),e.jsx(t,{id:"privacy",children:"Privacy"}),e.jsxs("ul",{className:"mt-4 list-disc space-y-2 pl-6 text-[16.5px] leading-[1.6]",children:[e.jsx("li",{children:'You appear everywhere under a pseudonym such as "Citizen 7F3A". Your email is used to sign in and for alerts you ask for, and is never shown.'}),e.jsx("li",{children:"Faces are blurred and phone metadata is removed before a photo is public. Exact photo locations are checked, not published."}),e.jsx("li",{children:"Originals stay in a private bucket, kept with their fingerprints so a dossier can be backed by them."}),e.jsx("li",{children:"Place checks need no account. A check is cached by area (about 150 m), not by person."}),e.jsx("li",{children:"Standing-water reports are shown at about 11 m precision, under your pseudonym. The exact position and the photo's metadata stay private."}),e.jsx("li",{children:"Rain heads-ups reach you through your own Amazon SNS topic, whose name is a code that says nothing about you."}),e.jsx("li",{children:"Officials' actions are logged with their pseudonym, role and the deciding rule."})]}),e.jsx(t,{id:"limits",children:"Limits"}),e.jsxs("ul",{className:"mt-4 list-disc space-y-2 pl-6 text-[16.5px] leading-[1.6]",children:[e.jsx("li",{children:"Pixels are 10 to 30 m. Ponds smaller than about half a hectare, narrow drains and thin channels are missed."}),e.jsx("li",{children:"Outlines are approximate. They are not a land survey and cannot settle a boundary dispute; revenue and survey records do that."}),e.jsx("li",{children:"The historic record ends in 2020. Change after that comes from the seasonal looks and the latest look."}),e.jsx("li",{children:"Land cover maps are model outputs with their own errors, especially between bare ground and built-up."}),e.jsx("li",{children:"Radar cannot see water between tall buildings, and one radar pass every 6 to 12 days can miss a flood that drains in hours."}),e.jsx("li",{children:"The letter is drafted by AI. Its numbers are checked; its tone and its reading of the law should be checked by you before you submit it."}),e.jsx("li",{children:"Summer heat is the temperature of the ground surface at about 10:30 to 11:00 in the morning, not the air temperature. Afternoons are hotter."}),e.jsx("li",{children:"Rain forecasts come from Open-Meteo and can be wrong. They are not official warnings."}),e.jsx("li",{children:"Standing-water reports are citizen data. Amazon Nova and verifiers check them, but a report can still be wrong or out of date."}),e.jsx("li",{children:"Translations are machine translations."})]}),e.jsx(t,{id:"data",children:"Data and credits"}),e.jsxs("ul",{className:"mt-4 space-y-2.5 text-[16px] leading-[1.55]",children:[e.jsxs("li",{children:[e.jsx("b",{children:"JRC Global Surface Water"})," 1984-2020, Pekel et al. (2016), European Commission Joint Research Centre. CC BY 4.0."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Landsat 4-9"})," Collection 2 Level-2, including the Landsat 8-9 surface temperature band, courtesy of the U.S. Geological Survey. Public domain."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Sentinel-2 and Sentinel-1"}),": contains modified Copernicus Sentinel data 2016-2026, processed by ESA. Sentinel-2 L2A from Earth Search by Element 84 on the Registry of Open Data on AWS; Sentinel-1 RTC from Microsoft Planetary Computer."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Copernicus DEM GLO-30"}),", © DLR e.V. 2010-2014 and © Airbus Defence and Space GmbH 2014-2018, provided under COPERNICUS by the European Union and ESA."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Impact Observatory"})," 10 m annual land use and land cover, with Esri and Microsoft. CC BY 4.0."]}),e.jsxs("li",{children:[e.jsx("b",{children:"ESA WorldCover"})," 2021, © ESA WorldCover project, contains modified Copernicus Sentinel data. CC BY 4.0."]}),e.jsxs("li",{children:[e.jsx("b",{children:"NASA POWER"})," monthly precipitation, NASA Langley Research Center POWER Project."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Rain forecasts"}),": weather data by Open-Meteo.com, CC BY 4.0, from its free API for non-commercial use. Rain categories from the India Meteorological Department."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Heat colour ramp"}),": ColorBrewer RdYlBu by Cynthia A. Brewer, Apache License 2.0."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Place and water-body names"}),": © OpenStreetMap contributors (ODbL), searched with Photon by Komoot; GeoNames (CC BY 4.0)."]}),e.jsxs("li",{children:[e.jsx("b",{children:"News"}),": headlines found through Google News search and the GDELT Project's open index of world news; each article stays on its publisher's site."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Base maps"}),": Amazon Location Service when deployed; OpenFreeMap and OpenStreetMap otherwise; imagery basemap by Esri."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Fonts"}),": Anek by Ek Type and Noto by Google, both under the SIL Open Font License."]})]}),e.jsx(t,{id:"open-source",children:"Open source and AWS"}),e.jsxs(a,{children:["JalSmriti uses three open-source projects from AWS: ",e.jsx("b",{children:"Strands Agents"})," for the letter-drafting agent, ",e.jsx("b",{children:"Cedar"})," for the access rules, and ",e.jsx("b",{children:"Powertools for AWS Lambda"})," for the API. Satellite data is read in place with GDAL and rasterio from cloud-optimised files, so no archive is copied. Maps are drawn with MapLibre GL JS and PDFs with fpdf2 and HarfBuzz."]}),e.jsx(a,{children:"On AWS, Step Functions with Distributed Map reads a whole city season by season in parallel Lambda functions, and a place check runs four branches at once (history and terrain, time-lapse, radar, summer heat); DynamoDB holds the lakes, evidence, ledgers and audit logs; S3 and CloudFront serve the site, the map layers, the reports and the audio; Cognito handles accounts; Bedrock, Translate, Rekognition and KMS do the drafting, translating, screening and signing; Polly reads reports aloud; SQS, SNS and EventBridge Scheduler run the photo pipeline, the email alerts, the daily rain check and the weekly satellite check; Location Service provides search and maps; CloudWatch watches it all. Everything is one CloudFormation stack that runs on a new account's free tier and credits."}),e.jsx(t,{id:"credit",children:"Who made it"}),e.jsxs(a,{children:["JalSmriti was made by ",e.jsx("b",{children:"Ansh Singhal"})," for WeMakeDevs × AWS Environmental Hacks 2026, in the Heat and Water track."]}),e.jsxs("div",{className:"mt-10 flex flex-wrap gap-3",children:[e.jsx(l,{className:"btn-primary",to:"/place",children:n("nav.check")}),e.jsx(l,{className:"btn-quiet",to:"/explore",children:n("nav.explore")})]})]})]})]})}export{k as default};
